//go:build ignore

// Copy into upstream converter/musicxml and run TestCodexZIP.
package musicxml
import ("archive/zip"; "bytes"; "encoding/binary"; "encoding/json"; "io"; "math/rand"; "os"; "path/filepath"; "testing")
func zip64(raw []byte) []byte {
 end:=len(raw)-22;if end<0{return raw};count:=binary.LittleEndian.Uint16(raw[end+10:]);size:=binary.LittleEndian.Uint32(raw[end+12:]);offset:=binary.LittleEndian.Uint32(raw[end+16:]);var out bytes.Buffer;out.Write(raw[:end]);var record [56]byte;binary.LittleEndian.PutUint32(record[:],0x06064b50);binary.LittleEndian.PutUint64(record[4:],44);binary.LittleEndian.PutUint16(record[12:],45);binary.LittleEndian.PutUint16(record[14:],45);binary.LittleEndian.PutUint64(record[24:],uint64(count));binary.LittleEndian.PutUint64(record[32:],uint64(count));binary.LittleEndian.PutUint64(record[40:],uint64(size));binary.LittleEndian.PutUint64(record[48:],uint64(offset));out.Write(record[:]);var loc [20]byte;binary.LittleEndian.PutUint32(loc[:],0x07064b50);binary.LittleEndian.PutUint64(loc[8:],uint64(end));binary.LittleEndian.PutUint32(loc[16:],1);out.Write(loc[:]);endRec:=append([]byte{},raw[end:]...);binary.LittleEndian.PutUint16(endRec[8:],65535);binary.LittleEndian.PutUint16(endRec[10:],65535);binary.LittleEndian.PutUint32(endRec[12:],0xffffffff);binary.LittleEndian.PutUint32(endRec[16:],0xffffffff);out.Write(endRec);return out.Bytes()
}
func TestCodexZIP(t *testing.T) {
 root:=os.Getenv("BDF_FIXTURE_ROOT");if root=="" {t.Fatal("BDF_FIXTURE_ROOT required")};r:=rand.New(rand.NewSource(451532));inputs:=[][]byte{}
 for n:=0;n<600;n++ {var b bytes.Buffer;w:=zip.NewWriter(&b);for j:=0;j<r.Intn(6);j++ {name:=[]string{"empty","foo.txt","日本.xml","../a","META-INF/container.xml","data.bin","folder"}[r.Intn(7)];h:=&zip.FileHeader{Name:name,Method:uint16(r.Intn(2)*8)};f,e:=w.CreateHeader(h);if e!=nil{t.Fatal(e)};p:=make([]byte,r.Intn(500));if j%2==0 {r.Read(p)} else {for k:=range p {p[k]=byte(r.Intn(6)+65)}};if _,e=f.Write(p);e!=nil{t.Fatal(e)}};if e:=w.Close();e!=nil{t.Fatal(e)};raw:=b.Bytes();inputs=append(inputs,append([]byte{},raw...));if len(raw)>22 && n%3==0 {mut:=append([]byte{},raw...);for k:=0;k<1+r.Intn(3);k++ {p:=r.Intn(len(mut));mut[p]^=byte(1+r.Intn(255))};inputs=append(inputs,mut)};if n%10==0 {inputs=append(inputs,zip64(raw))};if n%9==0 {inputs=append(inputs,append([]byte("executable-prefix"),raw...))};if n%10==0 {inputs=append(inputs,append([]byte{},raw[:r.Intn(len(raw))]...))}}
 actual,e:=os.ReadFile("testdata/ode_to_joy.mxl");if e!=nil{t.Fatal(e)};inputs=append(inputs,actual)
 out:=[]any{};for _,raw:=range inputs {var expected any;zr,e:=zip.NewReader(bytes.NewReader(raw),int64(len(raw)));if e==nil {entries:=[]any{};for _,f:=range zr.File {var content any=nil;rc,e:=f.Open();if e==nil {p,e:=io.ReadAll(rc);rc.Close();if e==nil && len(p)<=1048576 {content=[]int{};values:=make([]int,len(p));for i,c:=range p {values[i]=int(c)};content=values}};entries=append(entries,[]any{f.Name,int(f.Method),int(f.Flags),f.CompressedSize64,f.UncompressedSize64,content})};expected=entries};out=append(out,map[string]any{"input":raw,"want":expected})};b,e:=json.Marshal(out);if e!=nil{t.Fatal(e)};if e=os.WriteFile(filepath.Join(root,"compat/zip/cases.json"),b,0644);e!=nil{t.Fatal(e)}
}
